import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testCreateTribotsName() {
        Assert.assertEquals("Tribots", Robot.createTribots().name)
    }

    @Test
    fun testCreateTribotsTeam() {
        Assert.assertEquals(4215, Robot.createTribots().teamNumber)
    }

    @Test
    fun testCreateDefaultName() {
        Assert.assertEquals("Unknown", Robot.createDefault().name)
    }

    @Test
    fun testCreateDefaultTeam() {
        Assert.assertEquals(0, Robot.createDefault().teamNumber)
    }

    @Test
    fun testRegularConstructor() {
        val robot = Robot("Test Bot", 1234)
        Assert.assertEquals("Test Bot", robot.name)
        Assert.assertEquals(1234, robot.teamNumber)
    }
}
